SELECT C.name, V.Model_year, R.total_hours FROM Customers C JOIN Vehicles V ON C.id = Customers.id JOIN Vehicles V ON R.vehicles_id = V.id JOIN Renting_history R ON R.customer_id = C.id JOIN Discount D ON R.discount_id = D.id GROUP BY C.name, V.Model_year ORDER BY R.total_hours DESC;
