SELECT student_loan_id, amount_of_loan, date_of_loan FROM Student_Loans WHERE student_id IN (SELECT student_id FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id AND Transcripts.date_of_transcript >= '2023-01-01' AND Transcripts.date_of_transcript <= '2023-12-31') AND (SELECT COUNT(*) FROM Transcripts JOIN Students ON Transcripts.student_id = Students.student_id AND Transcripts.date_of_transcript >= '2023-01-01' AND Transcripts.date_of_transcript <= '2023-12-31') > 2;
SELECT S.student_id, S.amount_of_loan, S.date_of_loan, S.achievement_details, S.other_details FROM Students S JOIN Student_Loans L ON S.student_id = L.student_id JOIN Transcripts T ON L.student_id = T.student_id JOIN Behaviour_Monitoring B ON L.student_id = B.student_id JOIN Student_Events E ON L.student_id = E.student_id JOIN Students_Addresses A ON L.student_id = A.student_id JOIN Detention D ON L.student_id = D.student_id JOIN Ref_Achievement_Type A_T ON A.achievement_type_code = A_T.achievement_type_code JOIN Ref_Event_Types E_T ON E.event_type_code = E_T.event_type_code JOIN Ref_Address_Types A_T2 ON A.address_type_code = A_T2.address_type_code JOIN Ref_Detention_Type D_T ON D.detention_type_code = D_T.detention_type_code WHERE S.amount_of_loan > 0 AND S.date_of_loan IS NOT NULL AND S.achievement_details IS NOT NULL;
SELECT t.id, s.detail FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Classes c ON c.student_id = s.student_id JOIN Teachers t2 ON t2.teacher_id = c.teacher_id GROUP BY s.id, s.detail ORDER BY t2.teacher_id ASC
SELECT Students.id, Students.student_details FROM Students INNER JOIN Transcripts ON Transcripts.student_id = Students.student_id INNER JOIN Classes ON Classes.student_id = Transcripts.student_id INNER JOIN Teachers ON Teachers.teacher_id = Classes.teacher_id WHERE Classes.class_details LIKE '%large%';
