SELECT S.student_id, S.bio_data, S.student_details, B.behaviour_monitoring_details, T.transcript_details FROM Students S JOIN Behaviour_Monitoring B ON S.student_id = B.student_id JOIN Transcripts T ON S.student_id = T.student_id WHERE T.transcript_details IS NOT NULL AND B.behaviour_monitoring_details IS NOT NULL AND T.transcript_details IS NOT NULL AND B.behaviour_monitoring_details IS NOT NULL AND T.transcript_details = B.behaviour_monitoring_details AND T.transcript_details = (SELECT transcript_details FROM Transcripts T2 WHERE T2.student_id = S.student_id)
SELECT Students.student_id, Students.bio_data, Students.student_details, Students.Addresses.address_id, Addresses.address_details, Detention.detention_summary FROM Students JOIN Addresses ON Students.student_id = Addresses.student_id JOIN Detention ON Addresses.address_id = Detention.address_id WHERE Detention.detention_summary IS NULL;
SELECT DISTINCT student_id, bio_data, behaviour_monitoring_details FROM Students JOIN Behaviour_Monitoring ON Students.student_id = Behaviour_Monitoring.student_id WHERE Behaviour_Monitoring_details IS NOT NULL ORDER BY behaviour_monitoring_details DESC;
SELECT Students.student_id, Students.bio_data, Students.student_details, Student_Events.event_date FROM Students JOIN Student_Events ON Students.student_id = Student_Events.student_id JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code WHERE Student_Events.event_date IS NOT NULL;
SELECT Students.student_id, Students.bio_data, Student_Events.event_date FROM Students JOIN Student_Events ON Students.student_id = Student_Events.student_id;
SELECT COUNT(*) AS total_students, event_type_description AS event_type, transcript_details AS description FROM Student_Events JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code GROUP BY event_type ORDER BY COUNT(*) DESC;
