SELECT s.student_id, t.student_id, t.teacher_id, t.class_details FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Behaviour_Monitoring b ON s.student_id = b.student_id JOIN Student_Events e ON s.student_id = e.student_id JOIN Classes c ON e.student_id = c.student_id;
SELECT s.student_id, t.student_id, t.teacher_id, t.class_details FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Classes c ON c.student_id = s.student_id JOIN Behaviour_Monitoring b ON b.student_id = s.student_id JOIN Student_Events e ON e.student_id = s.student_id JOIN Student_Loans l ON l.student_id = s.student_id JOIN Detention d ON d.student_id = s.student_id;
SELECT COUNT(*) AS total_courses, teacher_id AS teacher_id FROM Classes GROUP BY teacher_id ORDER BY COUNT(*) DESC;
SELECT t.teacher_id, COUNT(t.class_id) AS number_of_courses FROM Classes t JOIN Students s ON t.student_id = s.student_id GROUP BY t.teacher_id ORDER BY number_of_courses DESC;
SELECT COUNT(*) AS max_courses, student_id AS student_id FROM Transcripts GROUP BY student_id ORDER BY COUNT(*) DESC LIMIT 1;
SELECT student_id, COUNT(transcript_details.transcript_id) AS total_courses FROM Transcripts INNER JOIN Students ON Transcripts.student_id = Students.student_id GROUP BY student_id;
SELECT student_id, student_details FROM Students JOIN Transcripts ON Transcripts.student_id = Students.student_id JOIN Behaviour_Monitoring ON Behaviour_Monitoring.student_id = Students.student_id;
SELECT s.student_id, s.bio_data, s.student_details, t.transcript_details, bm.behaviour_monitoring_details, ... FROM Students s JOIN Transcripts t ON s.student_id = t.student_id JOIN Behaviour_Monitoring bm ON s.student_id = bm.student_id;
SELECT R.detention_type_code, R.detention_type_description, R.detention_summary FROM Ref_Detention_Type R JOIN Detention D ON R.detention_type_code = D.detention_type_code WHERE D.student_id = (SELECT student_id FROM Students_Addresses WHERE address_type_code = 'B' AND date_from = '2023-01-01' AND date_to = '2023-01-31') ORDER BY R.detention_type_code ASC;
SELECT Detention.detention_type_code, Detention.detention_type_description FROM Detention JOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code ORDER BY Detention.detention_type_code ASC LIMIT 1;
SELECT Students.bio_data, Students.student_id, Students.student_details, Students_Addresses.address_id, Addresses.address_details, Detention.datetime_detention_start, Detention.datetime_detention_end, Detention.detention_summary FROM Students JOIN Students_Addresses ON Students.student_id = Students_Addresses.student_id JOIN Addresses ON Students_Addresses.address_id = Addresses.address_id JOIN Detention ON Detention.student_id = Students.student_id WHERE Student_Loans.amount_of_loan > (SELECT AVG(Other_Details) FROM Student_Loans)
SELECT Students.student_id, Students.bio_data, Students.student_details, Transcripts.transcript_details, Behaviour_Monitoring.behaviour_monitoring_details, Addresses.address_details, Ref_Event_Types.event_type_description, Ref_Achievement_Type.achievement_type_description, Ref_Address_Types.address_type_description, Detention.detention_summary FROM Students INNER JOIN Transcripts ON Transcripts.student_id = Students.student_id LEFT JOIN Behaviour_Monitoring ON Behaviour_Monitoring.student_id = Students.student_id LEFT JOIN Addresses ON Addresses.address_id = Students_Addresses.address_id LEFT JOIN Ref_Address_Types ON Ref_Address_Types.address_type_code = Students_Addresses.address_type_code LEFT JOIN Ref_Detention_Type ON Detention.detention_type_code = Ref_Detention_Type.detention_type_code LEFT JOIN Detention ON Detention.student_id = Students.student_id LEFT JOIN Ref_Event_Types ON Student_Events.event_type_code = Ref_Event_Types.event_type_code LEFT JOIN Ref_Achievement_Type ON Achievements.achievement_type_code = Ref_Achievement_Type.achievement_type_code LEFT JOIN Achievements ON Achievements.student_id = Students.student_id;
SELECT MIN(date_of_loan) FROM Student_Loans;
SELECT MIN(date_of_loan) FROM Student_Loans;
SELECT s.bio_data, s.student_details, t.date_of_transcript FROM Students s JOIN Transcripts t ON s.student_id = t.student_id WHERE t.date_of_transcript IS NULL;
