SELECT countries.name, countries.overall_score, countries.justice_score, countries.health_score, countries.economics_score, countries.politics_score, countries.education_score FROM countries ORDER BY education_score DESC;
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.overall_score ORDER BY countries.overall_score DESC;
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.overall_score ORDER BY countries.overall_score DESC LIMIT 1;
SELECT countries.name, languages.name AS official_language FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id;
SELECT countries.name, languages.name AS official_language FROM countries JOIN languages ON countries.id = languages.country_id;
SELECT languages.name, COUNT(countries.id) AS number_of_countries FROM languages JOIN countries ON languages.id = countries.language_id GROUP BY languages.name
SELECT languages.name, COUNT(countries.id) AS country_count FROM languages JOIN countries ON languages.id = countries.language_id GROUP BY languages.name
SELECT countries.name, languages.name AS official_language FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.id ORDER BY languages.name DESC LIMIT 1
SELECT languages.name, countries.name AS country_name, official_languages.name AS language_name FROM languages JOIN countries ON languages.id = countries.id JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.name = (SELECT name FROM languages) ORDER BY language_name DESC LIMIT 1;
SELECT l.name, c.name AS country_name FROM countries c JOIN official_languages ol ON c.id = ol.country_id GROUP BY c.id, l.name HAVING COUNT(l.name) >= 2
SELECT DISTINCT l.name AS language, c.name AS country FROM languages l JOIN countries c ON l.id = c.id WHERE c.id IN (SELECT country_id FROM official_languages WHERE language_id = l.id GROUP BY language_id HAVING COUNT(country_id) > 1)
SELECT AVG(countries.overall_score) AS average_overall_score FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE official_languages.language_id = languages.id AND languages.name = 'English'
SELECT AVG(countries.overall_score) FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE languages.name = 'English'
SELECT languages.name, countries.name, official_languages.language_id FROM languages INNER JOIN official_languages ON languages.id = official_languages.language_id INNER JOIN countries ON countries.id = official_languages.country_id ORDER BY languages.name DESC LIMIT 3;
SELECT DISTINCT l.name, o.country_id FROM languages l JOIN official_languages o ON l.id = o.language_id JOIN countries c ON o.country_id = c.id WHERE c.overall_score ORDER BY c.overall_score DESC LIMIT 3;
SELECT languages.name, countries.overall_score, countries.justice_score, countries.health_score, countries.education_score, countries.economics_score, countries.politics_score, countries.id FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id ORDER BY languages.name DESC;
SELECT languages.name, countries.name AS country_name, languages.name AS language_name FROM languages JOIN countries ON languages.id = countries.id JOIN official_languages ON countries.id = official_languages.country_id GROUP BY languages.id, countries.name ORDER BY countries.name DESC;
SELECT countries.name, languages.name AS language_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.name ORDER BY languages.name DESC;
SELECT countries.name, languages.name AS language_name FROM countries JOIN official_languages ON countries.id = official_languages.country_id JOIN languages ON official_languages.language_id = languages.id GROUP BY countries.id ORDER BY languages.name DESC;
SELECT languages.name FROM languages JOIN official_languages ON languages.id = official_languages.language_id WHERE countries.id IS NULL
SELECT languages.name FROM languages JOIN official_languages ON languages.id = official_languages.language_id WHERE official_languages.country_id IS NULL
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.overall_score IS NULL OR countries.justice_score IS NULL OR countries.health_score IS NULL OR countries.education_score IS NULL OR countries.economics_score IS NULL OR countries.politics_score IS NULL;
SELECT countries.name FROM countries JOIN official_languages ON countries.id = official_languages.country_id WHERE countries.overall_score IS NULL OR countries.justice_score IS NULL OR countries.health_score IS NULL OR countries.education_score IS NULL OR countries.economics_score IS NULL OR countries.politics_score IS NULL;
SELECT languages.name FROM languages JOIN countries ON languages.id = countries.id WHERE countries.overall_score > 95 AND countries.overall_score < 90;
SELECT languages.name FROM languages INNER JOIN countries ON languages.id = countries.id WHERE countries.overall_score > 95 OR countries.overall_score < 90
