SELECT Features.feature_description FROM Features;
SELECT Features.feature_name, Features.feature_description FROM Features INNER JOIN Property_Features ON Features.feature_id = Property_Features.feature_id WHERE feature_name = 'rooftop'
SELECT Features.feature_name, Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id JOIN Properties ON Property_Features.property_id = Properties.property_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Rooms.room_type_code = Ref_Room_Types.room_type_code GROUP BY Features.feature_id ORDER BY Feature_Name ASC LIMIT 1;
SELECT Features.feature_name, Features.feature_description FROM Features JOIN Property_Features ON Features.feature_id = Property_Features.feature_id JOIN Properties ON Property_Features.property_id = Properties.property_id GROUP BY Features.feature_id ORDER BY Feature_description ASC LIMIT 1
SELECT MIN(room_count) FROM Rooms;
SELECT MIN(room_count) FROM Properties;
SELECT COUNT(DISTINCT property_name) FROM Properties WHERE garage_yn OR parking_lots = 1;
SELECT COUNT(*) FROM Properties WHERE garage_yn OR parking_lots;
SELECT Users.age_category_code, Users.user_category_code FROM Users INNER JOIN Ref_Age_Categories ON Users.age_category_code = Ref_Age_Categories.age_category_code WHERE Users.description LIKE '%Mother%';
SELECT DISTINCT user_category_code, user_address_id, first_name, last_name FROM Users WHERE first_name OR last_name LIKE '%Mother%' UNION ALL SELECT age_category_code, user_address_id, age_category_description FROM Ref_Age_Categories WHERE age_category_description LIKE '%Mother%'
SELECT Users.first_name, Properties.owner_user_id FROM Users JOIN Properties ON Users.user_id = Properties.owner_user_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Properties.room_count = Ref_Room_Types.room_count JOIN Property_Photos ON Properties.property_id = Property_Photos.property_id JOIN Property_Features ON Properties.property_id = Property_Features.property_id JOIN Features ON Property_Features.feature_id = Features.feature_id GROUP BY Users.first_name ORDER BY Properties.owner_user_id ASC LIMIT 1;
SELECT Users.first_name FROM Users JOIN Properties ON Users.user_address_id = Properties.property_address_id JOIN Ref_Property_Types ON Properties.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Properties.room_count = Ref_Room_Types.room_count JOIN Property_Photos ON Properties.property_id = Property_Photos.property_id JOIN Property_Features ON Property_Features.feature_id = Property_Features.property_id JOIN Features ON Property_Features.feature_id = Features.feature_id JOIN Users ON Users.user_id = Property_Features.feature_id JOIN Users ON Users.user_id = Property_Features.feature_id JOIN Ref_User_Categories ON Users.user_category_code = Ref_User_Categories.user_category_code JOIN Ref_Property_Types ON Users.age_category_code = Ref_Property_Types.age_category_code JOIN Ref_Room_Types ON Users.room_type_code = Ref_Room_Types.room_type_code JOIN Ref_Property_Types ON Users.user_category_code = Ref_Property_Types.age_category_code JOIN Ref_Room_Types ON Users.room_type_code = Ref_Room_Types.room_type_code;
SELECT AVG(room_count) AS average_room_count FROM Properties WHERE property_type_code = 'Garden' AND property_address_id = (SELECT address_id FROM Addresses WHERE town_city = 'Garden City')
SELECT AVG(room_count) FROM Properties WHERE property_description LIKE '%garden%'
SELECT Addresses.town_city, Properties.property_name, Properties.property_description FROM Addresses JOIN Properties ON Addresses.address_id = Properties.property_address_id WHERE Properties.property_type_code = 'Swimming_Pool' AND Properties.owner_user_id = Users.user_id;
SELECT Addresses.town_city, Addresses.zip_postcode, Addresses.county_state_province, Addresses.country, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality, Addresses.town_city, Addresses.zip_postcode, Addresses.county_state_province, Addresses.country, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality FROM Addresses JOIN Properties ON Addresses.address_id = Properties.property_address_id JOIN Users ON Users.user_address_id = Properties.owner_user_id WHERE Properties.property_type_code = 'Swimming Pools' AND Properties.property_address_id IS NOT NULL;
SELECT Property_Photos.photo_title, Properties.price_min, Properties.price_max, Properties.property_name, Properties.property_description, Properties.vendor_requested_price, Properties.price_min, Properties.price_max, Properties.vendor_requested_price FROM Properties INNER JOIN Property_Photos ON Properties.property_id = Property_Photos.property_id ORDER BY Properties.price_min ASC LIMIT 1;
SELECT p.property_id, p.vendor_requested_price FROM Properties p WHERE p.vendor_requested_price = (SELECT MIN(v.vendor_requested_price) FROM Users v) ORDER BY p.vendor_requested_price;
SELECT AVG(Rooms.room_count) AS average_rooms FROM Rooms INNER JOIN Properties ON Rooms.property_id = Properties.room_count;
SELECT AVG(rooms.room_count) FROM Rooms INNER JOIN Properties ON Rooms.property_id = Properties.property_id
SELECT COUNT(*) FROM Rooms;
