SELECT COUNT(*) FROM Users WHERE is_buyer = TRUE;
SELECT COUNT(*) FROM Users WHERE is_buyer = '1'
SELECT date_registered FROM Users WHERE login_name = 'ratione' LIMIT 1
SELECT date_registered FROM Users WHERE login_name = 'ratione' AND is_buyer = 'Y' AND is_seller = 'N'
SELECT Users.first_name, Users.middle_name, Users.last_name, Users.login_name FROM Users INNER JOIN Property_Features ON Users.user_id = Property_Features.user_id WHERE Property_Features.feature_value = 1;
SELECT Users.login_name, Users.first_name, Users.middle_name, Users.last_name FROM Users INNER JOIN Addresses ON Users.user_address_id = Addresses.address_id INNER JOIN Ref_Property_Types ON Addresses.address_id = Properties.property_type_code INNER JOIN Properties ON Addresses.address_id = Properties.owner_user_id INNER JOIN Users ON Users.user_id = Users.user_address_id;
SELECT Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.town_city FROM Addresses JOIN Users ON Addresses.address_id = Users.user_address_id WHERE Users.is_seller = 1;
SELECT Addresses.address_id, Addresses.line_1_number_building, Addresses.line_2_number_street, Addresses.line_3_area_locality, Addresses.town_city, Addresses.zip_postcode, Addresses.county_state_province, Addresses.country, Addresses.other_address_details FROM Addresses JOIN Users ON Addresses.user_address_id = Users.user_address_id JOIN Ref_Property_Types ON Addresses.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON Addresses.room_type_code = Ref_Room_Types.room_type_code JOIN Ref_Property_Types ON Addresses.property_type_code = Ref_Property_Types.property_type_code;
SELECT COUNT(*) FROM Properties WHERE Property_Description IS NOT NULL AND Date_OffMarket IS NOT NULL AND Date_OnMarket IS NOT NULL AND Property_Description LIKE '%2%'
SELECT COUNT(DISTINCT property_name) FROM Properties WHERE date_on_market >= (SELECT MAX(date_on_market) FROM Properties) AND date_off_market <= (SELECT MAX(date_off_market) FROM Properties)
SELECT COUNT(DISTINCT property_name) FROM Properties;
SELECT COUNT(DISTINCT property_id) AS count FROM Properties;
SELECT Users.user_id, COUNT(Properties.property_id) AS number_of_photos FROM Users INNER JOIN Users ON Users.user_id = Users.user_id GROUP BY Users.user_id;
SELECT p.owner_user_id, COUNT(p.owner_user_id) AS count_per_owner FROM Properties p JOIN Property_Photos p_photos ON p.property_id = p_photos.property_id JOIN Ref_Property_Types ON p.property_type_code = Ref_Property_Types.property_type_code JOIN Ref_Room_Types ON p.room_count = Ref_Room_Types.room_count GROUP BY p.owner_user_id
SELECT MAX(price_max) FROM Properties WHERE price_max IS NOT NULL AND owner_user_id IN (SELECT user_id FROM Users WHERE user_category_code IN ('single_mother') OR user_category_code IN ('student'))
