SELECT Staff.staff_id, Staff.staff_details FROM Staff JOIN Staff_in_Processes ON Staff.staff_id = Staff_in_Processes.staff_id JOIN Documents_Processes ON Staff_in_Processes.document_id = Documents_Processes.document_id JOIN Documents ON Documents.document_id = Documents_Processes.document_id JOIN Process_Outcomes ON Documents.Process_Outcome_Code = Documents_Processes.process_outcome_code JOIN Process_Status ON Documents.Process_Status_Code = Documents_Processes.process_status_code;
SELECT staff_details FROM Staff WHERE staff_id = 100;
SELECT COUNT(*) AS number_of_staff_roles FROM Staff;
SELECT Ref_Staff_Roles.staff_role_code, Ref_Staff_Roles.staff_role_description FROM Ref_Staff_Roles;
SELECT Ref_Staff_Roles.staff_role_description FROM Ref_Staff_Roles INNER JOIN Staff ON Ref_Staff_Roles.staff_role_code = Staff.staff_role_code WHERE Staff.staff_id = (SELECT staff_id FROM Staff WHERE staff_details LIKE 'HR') AND Ref_Staff_Roles.staff_role_code = (SELECT staff_role_code FROM Ref_Staff_Roles WHERE staff_details LIKE 'HR')
SELECT COUNT(DISTINCT documents.document_id) FROM Documents;
SELECT D.document_id, D.author_name, D.document_name, D.document_description, D.other_details, P.process_id, P.process_name, P.process_description, P.process_status_code, P.process_status_description FROM Documents D JOIN Business_Processes P ON D.document_id = P.document_id JOIN Process_Outcomes PO ON D.process_outcome_code = PO.process_outcome_code JOIN Process_Status PS ON D.process_status_code = PS.process_status_code JOIN Ref_Staff_Roles R ON D.staff_id = R.staff_id JOIN Staff IN Processes SP ON SP.staff_id = D.staff_id JOIN Process_Status PS ON SP.process_id = PS.process_status_code JOIN Process_Outcomes PO ON SP.process_outcome_code = PO.process_outcome_code;
SELECT D.document_id, D.author_name, D.document_name, D.document_description, D.other_details FROM Documents D WHERE D.process_outcome_code IS NULL UNION ALL SELECT D.document_id, D.author_name, D.document_name, D.document_description, D.other_details FROM Documents D WHERE D.process_outcome_code IS NULL
SELECT DISTINCT staff.staff_id FROM Staff JOIN Staff_in_Processes ON Staff.staff_id = Staff_in_Processes.staff_id WHERE Staff_in_Processes.process_id IS NULL
SELECT Process_Outcomes.process_outcome_description, Process_Status.process_status_description FROM Process_Outcomes INNER JOIN Process_Status ON Process_Outcomes.process_outcome_code = Process_Status.process_status_code WHERE Documents.document_id = 0;
SELECT process_name FROM Business_Processes JOIN Documents ON Documents.document_id = Documents_Processes.document_id JOIN Documents_Processes ON Documents_Processes.process_id = Business_Processes.process_id JOIN Documents ON Documents.document_id = Documents_Processes.document_id JOIN Staff_in_Processes ON Documents_Processes.process_id = Staff_in_Processes.process_id JOIN Staff ON Staff.staff_id = Staff_in_Processes.staff_id JOIN Ref_Staff_Roles ON Staff_in_Processes.staff_id = Ref_Staff_Roles.staff_id JOIN Process_Outcomes ON Staff_in_Processes.process_outcome_code = Process_Outcomes.process_outcome_code JOIN Process_Status ON Staff_in_Processes.process_status_code = Process_Status.process_status_code;
SELECT process_id, COUNT(DOCUMENTS.Process_Outcomes.process_outcome_code) AS document_count FROM Documents_Processes INNER JOIN Documents ON Documents.document_id = Documents_Processes.document_id GROUP BY process_id;
SELECT COUNT(*) FROM Documents_Processes WHERE process_id = 9 AND document_id = 0
SELECT staff_id, COUNT(DOCUMENTS.Process_Outcomes.process_outcome_code) AS process_count FROM Staff JOIN Staff_in_Processes ON Staff.staff_id = Staff_in_Processes.staff_id JOIN Documents_Processes ON Staff_in_Processes.document_id = Documents_Processes.document_id JOIN Documents ON Documents.document_id = Documents_Processes.document_id GROUP BY staff_id;
SELECT Ref_Staff_Roles.staff_role_code, COUNT(DOCUMENTS.Process_Outcomes.process_outcome_code) AS process_count FROM Ref_Staff_Roles INNER JOIN Documents_Processes ON Ref_Staff_Roles.staff_role_code = Documents_Processes.process_outcome_code GROUP BY Ref_Staff_Roles.staff_role_code;
