SELECT Clients.client_id, Clients.client_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Staff.agency_id = Agencies.agency_id JOIN Staff_in_Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id JOIN Meetings ON Staff_in_Meetings.staff_id = Staff.staff_id;
SELECT Clients.client_id, Clients.client_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Clients.agency_id = Staff.agency_id JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
