SELECT agency_id, COUNT(*) AS client_count, staff_id, staff_details FROM Agencies INNER JOIN Staff ON Agencies.agency_id = Staff.agency_id INNER JOIN Clients ON Clients.agency_id = Agencies.agency_id GROUP BY agency_id ORDER BY COUNT(*) DESC;
