SELECT Clients.client_id, Clients.client_details, Agencies.agency_details, Staff.staff_id, Staff.staff_details FROM Clients JOIN Agencies ON Clients.agency_id = Agencies.agency_id JOIN Staff ON Clients.client_id = Staff.client_id JOIN Staff_in_Meetings ON Staff.staff_id = Staff_in_Meetings.staff_id JOIN Meetings ON Staff_in_Meetings.meeting_id = Meetings.meeting_id;
